3D poster card showcase, large card nearly filling frame, colored backgrounds. 16s, 1920x1080, SILENT. Card size 500x750px centered. Background changes color per card: card1=deep amber/gold gradient, card2=deep navy/blue gradient, card3=deep crimson/red gradient. Card has glow, specular sweep, rocking animation. Name below card only
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
/* colored background panels — one per card */
bg-panel{
position:absolute;inset:0;opacity:0
transition:opacity 0s
}
#bg1{background:radial-gradient(ellipse at 50% 40%, #3a2800 0%, #1a1000 55%, #0a0600 100%);}
#bg2{background:radial-gradient(ellipse at 50% 40%, #001435 0%, #000a22 55%, #000510 100%);}
#bg3{background:radial-gradient(ellipse at 50% 40%, #2a0008 0%, #180005 55%, #0a0003 100%);}
/* ambient glow */
glow-bg{
position:absolute
width:700px;height:900px
border-radius:50%
filter:blur(100px)
opacity:0;z-index:1
}
card-stage{
position:absolute;z-index:5
display:flex;flex-direction:column;align-items:center
opacity:0
}
/* larger card */
card-wrap{
width:500px;height:750px
position:relative;z-index:2
}
card-face{
width:100%;height:100%
border-radius:10px;overflow:hidden;position:relative
}
card-face img{
width:100%;height:100%
object-fit:cover;object-position:center top;display:block
}
/* specular sweep */
card-face::after{
content:""
position:absolute;top:0;left:-70%
width:45%;height:100%
background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,0.16) 50%,transparent 70%)
animation:specular 2.4s ease-in-out infinite alternate
pointer-events:none;z-index:2
}
@keyframes specular{from{left:-70%;}to{left:125%;}}
/* per-card glow */
#s1 .card-face{
box-shadow:0 0 0 2px rgba(255,200,80,0.5),0 0 60px rgba(255,160,30,0.45),0 30px 80px rgba(0,0,0,0.85)
animation:glowA 2s ease-in-out infinite alternate
}
#s1 .glow-bg{background:radial-gradient(ellipse,rgba(255,140,20,0.50),transparent 70%);}
@keyframes glowA{
from{box-shadow:0 0 0 1px rgba(255,200,80,0.3),0 0 30px rgba(255,160,30,0.25),0 30px 80px rgba(0,0,0,0.85);}
to  {box-shadow:0 0 0 3px rgba(255,220,100,0.65),0 0 80px rgba(255,180,40,0.55),0 30px 80px rgba(0,0,0,0.85);}
}
#s2 .card-face{
box-shadow:0 0 0 2px rgba(80,160,255,0.5),0 0 60px rgba(40,120,255,0.45),0 30px 80px rgba(0,0,0,0.85)
animation:glowB 2s ease-in-out infinite alternate
}
#s2 .glow-bg{background:radial-gradient(ellipse,rgba(30,100,255,0.45),transparent 70%);}
@keyframes glowB{
from{box-shadow:0 0 0 1px rgba(80,160,255,0.3),0 0 30px rgba(40,120,255,0.25),0 30px 80px rgba(0,0,0,0.85);}
to  {box-shadow:0 0 0 3px rgba(120,190,255,0.65),0 0 80px rgba(60,150,255,0.55),0 30px 80px rgba(0,0,0,0.85);}
}
#s3 .card-face{
box-shadow:0 0 0 2px rgba(220,60,60,0.5),0 0 60px rgba(180,30,30,0.45),0 30px 80px rgba(0,0,0,0.85)
animation:glowC 2s ease-in-out infinite alternate
}
#s3 .glow-bg{background:radial-gradient(ellipse,rgba(180,20,20,0.45),transparent 70%);}
@keyframes glowC{
from{box-shadow:0 0 0 1px rgba(220,60,60,0.3),0 0 30px rgba(180,30,30,0.25),0 30px 80px rgba(0,0,0,0.85);}
to  {box-shadow:0 0 0 3px rgba(255,80,80,0.65),0 0 80px rgba(220,40,40,0.55),0 30px 80px rgba(0,0,0,0.85);}
}
role-label{
margin-top:26px;text-align:center;opacity:0;z-index:5
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:52px;font-weight:700
color:#f0ece4;line-height:.90;letter-spacing:-.01em
}
#open-fade,#close-fade{
position:absolute;inset:0;z-index:50;background:#000;pointer-events:none
}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="bg1" class="bg-panel"></div>
<div id="bg2" class="bg-panel"></div>
<div id="bg3" class="bg-panel"></div>
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="card-stage" id="s1">
<div class="glow-bg"></div>
<div class="card-wrap" id="w1">
<div class="card-face"><img src="{{p1}}" alt=""></div>
</div>
<div class="role-label" id="l1"><div class="role-name">Alan Turing</div></div>
</div>
<div class="card-stage" id="s2">
<div class="glow-bg"></div>
<div class="card-wrap" id="w2">
<div class="card-face"><img src="{{p2}}" alt=""></div>
</div>
<div class="role-label" id="l2"><div class="role-name">Sherlock Holmes</div></div>
</div>
<div class="card-stage" id="s3">
<div class="glow-bg"></div>
<div class="card-wrap" id="w3">
<div class="card-face"><img src="{{p3}}" alt=""></div>
</div>
<div class="role-label" id="l3"><div class="role-name">Hamlet</div></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
function startRock(wrap){
gsap.set(wrap,{transformPerspective:1000,rotateX:4,rotateY:-18})
gsap.to(wrap,{rotateY:18,rotateX:2.5,duration:1.2,ease:'sine.inOut',repeat:-1,yoyo:true})
}
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.45,ease:'power2.out'},0.0)
/* CARD 1 — amber bg */
tl.to('#bg1',{opacity:1,duration:0.6,ease:'power2.out'},0.35)
tl.set('#s1',{opacity:1},0.4)
tl.to('#s1 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},0.4)
tl.to('#s1',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.78}},0.4)
tl.to('#l1',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:14}},0.8)
tl.call(function(){startRock(document.querySelector('#w1'));},null,0.4)
tl.to(['#s1 .glow-bg','#l1'],{opacity:0,duration:0.35},4.5)
tl.to('#bg1',{opacity:0,duration:0.4,ease:'power2.in'},4.5)
tl.to('#s1',{opacity:0,scale:0.82,duration:0.4,ease:'power2.in'},4.55)
tl.call(function(){gsap.killTweensOf('#w1');},null,4.95)
tl.set('#s1',{opacity:0},5.0)
/* CARD 2 — blue bg */
tl.to('#bg2',{opacity:1,duration:0.6,ease:'power2.out'},4.9)
tl.set('#s2',{opacity:1},4.95)
tl.to('#s2 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},4.95)
tl.to('#s2',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.78}},4.95)
tl.to('#l2',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:14}},5.35)
tl.call(function(){startRock(document.querySelector('#w2'));},null,4.95)
tl.to(['#s2 .glow-bg','#l2'],{opacity:0,duration:0.35},9.5)
tl.to('#bg2',{opacity:0,duration:0.4,ease:'power2.in'},9.5)
tl.to('#s2',{opacity:0,scale:0.82,duration:0.4,ease:'power2.in'},9.55)
tl.call(function(){gsap.killTweensOf('#w2');},null,9.95)
tl.set('#s2',{opacity:0},10.0)
/* CARD 3 — crimson bg */
tl.to('#bg3',{opacity:1,duration:0.6,ease:'power2.out'},9.9)
tl.set('#s3',{opacity:1},9.95)
tl.to('#s3 .glow-bg',{opacity:1,duration:0.6,ease:'power2.out'},9.95)
tl.to('#s3',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.78}},9.95)
tl.to('#l3',{opacity:1,y:0,duration:0.45,ease:'power3.out',startAt:{y:14}},10.35)
tl.call(function(){startRock(document.querySelector('#w3'));},null,9.95)
tl.to(['#s3 .glow-bg','#l3'],{opacity:0,duration:0.35},14.5)
tl.to('#bg3',{opacity:0,duration:0.4,ease:'power2.in'},14.5)
tl.to('#s3',{opacity:0,scale:0.82,duration:0.4,ease:'power2.in'},14.55)
tl.to('#close-fade',{opacity:1,duration:0.65,ease:'power2.inOut'},14.7)
tl.set('#close-fade',{opacity:1},15.5)
})
</script>
</body>
</html>
```
